import threading

# BROKEN: no synchronization, race condition waiting to happen
class NaiveBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.items = []

    def produce(self, item):
        # Gap between check and mutation, another thread can slip in here
        if len(self.items) < self.capacity:
            self.items.append(item)

    def consume(self):
        if len(self.items) > 0:
            return self.items.pop(0)
        return None

    def size(self):
        return len(self.items)

# Multiple producer threads calling produce() on the same
# NaiveBuffer with zero locking around the list.

if __name__ == "__main__":
    capacity = 100
    buffer = NaiveBuffer(capacity)
    producer_count = 5
    items_per_producer = 50  # 250 attempts total against a capacity of 100

    def produce_many():
        for i in range(items_per_producer):
            buffer.produce(i)

    threads = [threading.Thread(target=produce_many) for _ in range(producer_count)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    print(f"Capacity was: {capacity}")
    print(f"Final size after concurrent producers: {buffer.size()}")
    print("(With no locking, this can land above capacity, below it, or even "
          "raise an error, depending on timing. That is the bug.)")

