// BROKEN: no synchronization, race condition waiting to happen
class NaiveBuffer {
    private final int capacity;
    private final java.util.List<Integer> items = new java.util.ArrayList<>();

    NaiveBuffer(int capacity) {
        this.capacity = capacity;
    }

    void produce(int item) {
        // Check and mutate are two separate steps, not atomic together
        if (items.size() < capacity) {
            items.add(item);
        }
    }

    Integer consume() {
        if (items.size() > 0) {
            return items.remove(0);
        }
        return null;
    }

    int size() {
        return items.size();
    }
}

// Several Thread instances calling produce/consume concurrently
// on the same NaiveBuffer, with no lock guarding the ArrayList.

public class Main {
    public static void main(String[] args) throws InterruptedException {
        int capacity = 100;
        NaiveBuffer buffer = new NaiveBuffer(capacity);
        int producerCount = 5;
        int itemsPerProducer = 50; // 250 attempts total against a capacity of 100

        Thread[] producers = new Thread[producerCount];
        for (int p = 0; p < producerCount; p++) {
            producers[p] = new Thread(() -> {
                for (int i = 0; i < itemsPerProducer; i++) {
                    buffer.produce(i);
                }
            });
        }
        for (Thread t : producers) t.start();
        for (Thread t : producers) t.join();

        System.out.println("Capacity was: " + capacity);
        System.out.println("Final size after concurrent producers: " + buffer.size());
        System.out.println("(With no locking, this can land above capacity, " +
                "below it, or even throw, depending on timing. That is the bug.)");
    }
}

