    std::vector<std::thread> producers;
    for (int p = 0; p < producerCount; p++) {
        producers.emplace_back([&buffer, itemsPerProducer]() {
            for (int i = 0; i < itemsPerProducer; i++) {
                buffer.produce(i);
            }
