class BoundedBuffer {
  constructor(capacity) {
    this.capacity = capacity;
    this.items = [];
    this.waitingProducers = [];
    this.waitingConsumers = [];
  }

  async produce(item) {
    while (this.items.length >= this.capacity) {
      await new Promise((resolve) => this.waitingProducers.push(resolve));
    }
    this.items.push(item);
    if (this.waitingConsumers.length > 0) {
      this.waitingConsumers.shift()(); // notify one waiting consumer
    }
  }

  async consume() {
    while (this.items.length === 0) {
      await new Promise((resolve) => this.waitingConsumers.push(resolve));
    }
    const item = this.items.shift();
    if (this.waitingProducers.length > 0) {
      this.waitingProducers.shift()(); // notify one waiting producer
    }
    return item;
  }
}

