# CORRECT: explicit wait/notify using threading.Condition
import threading

class BoundedBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.items = []
        self.condition = threading.Condition()

    def produce(self, item):
        with self.condition:
            while len(self.items) >= self.capacity:
                self.condition.wait()  # release lock, sleep, reacquire on wake
            self.items.append(item)
            self.condition.notify_all()  # wake any waiting consumer

    def consume(self):
        with self.condition:
            while len(self.items) == 0:
                self.condition.wait()
            item = self.items.pop(0)
            self.condition.notify_all()  # wake any waiting producer
            return item


if __name__ == "__main__":
    buffer = BoundedBuffer(3)

    def produce_five():
        for i in range(1, 6):
            buffer.produce(i)
            print(f"produced {i}")

    def consume_five():
        for _ in range(1, 6):
            item = buffer.consume()
            print(f"consumed {item}")

    producer = threading.Thread(target=produce_five)
    consumer = threading.Thread(target=consume_five)
    producer.start()
    consumer.start()
    producer.join()
    consumer.join()

