// CORRECT: explicit wait/notify using synchronized and Object monitor
class BoundedBuffer {
    private final int capacity;
    private final java.util.LinkedList<Integer> items = new java.util.LinkedList<>();
    private final Object lock = new Object();

    BoundedBuffer(int capacity) {
        this.capacity = capacity;
    }

    void produce(int item) throws InterruptedException {
        synchronized (lock) {
            while (items.size() >= capacity) {
                lock.wait(); // release lock, sleep, reacquire on wake
            }
            items.add(item);
            lock.notifyAll(); // wake any waiting consumer
        }
    }

    int consume() throws InterruptedException {
        synchronized (lock) {
            while (items.isEmpty()) {
                lock.wait();
            }
            int item = items.removeFirst();
            lock.notifyAll(); // wake any waiting producer
            return item;
        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer buffer = new BoundedBuffer(3);

        Thread producer = new Thread(() -> {
            for (int i = 1; i <= 5; i++) {
                try {
                    buffer.produce(i);
                    System.out.println("produced " + i);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        Thread consumer = new Thread(() -> {
            for (int i = 1; i <= 5; i++) {
                try {
                    int item = buffer.consume();
                    System.out.println("consumed " + item);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
    }
}

