// CORRECT: explicit wait/notify using std::mutex and std::condition_variable
#include <iostream>
#include <deque>
#include <mutex>
#include <condition_variable>
#include <thread>

class BoundedBuffer {
private:
    int capacity;
    std::deque<int> items;
    std::mutex mtx;
    std::condition_variable cv;

public:
    explicit BoundedBuffer(int capacity) : capacity(capacity) {}

    void produce(int item) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return static_cast<int>(items.size()) < capacity; });
        items.push_back(item);
        cv.notify_all(); // wake any waiting consumer
    }

    int consume() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return !items.empty(); });
        int item = items.front();
        items.pop_front();
        cv.notify_all(); // wake any waiting producer
        return item;
    }
};

int main() {
    BoundedBuffer buffer(3);

    std::thread producer([&buffer]() {
        for (int i = 1; i <= 5; i++) {
            buffer.produce(i);
            std::cout << "produced " << i << std::endl;
        }
    });

    std::thread consumer([&buffer]() {
        for (int i = 1; i <= 5; i++) {
            int item = buffer.consume();
            std::cout << "consumed " << item << std::endl;
        }
    });

    producer.join();
    consumer.join();
    return 0;
}

