#include <iostream>
#include <deque>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <string>

class BoundedBuffer {
private:
    int capacity;
    std::deque<std::string> items;
    std::mutex mtx;
    std::condition_variable cv;

public:
    explicit BoundedBuffer(int capacity) : capacity(capacity) {}

    void produce(const std::string& item) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return static_cast<int>(items.size()) < capacity; });
        items.push_back(item);
        cv.notify_all();
    }

    std::string consume() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return !items.empty(); });
        std::string item = items.front();
        items.pop_front();
        cv.notify_all();
        return item;
    }
};

// Full example: 2 producers, 2 consumers, one bounded buffer
void producerLoop(BoundedBuffer& buffer, int pid, int count) {
    for (int i = 0; i < count; i++) {
        buffer.produce("item-" + std::to_string(pid) + "-" + std::to_string(i));
        std::cout << "producer " << pid << " added item " << i << std::endl;
    }
}

void consumerLoop(BoundedBuffer& buffer, int cid, int count) {
    for (int i = 0; i < count; i++) {
        std::string item = buffer.consume();
        std::cout << "consumer " << cid << " took " << item << std::endl;
    }
}

int main() {
    BoundedBuffer buffer(5);
    std::vector<std::thread> threads;
    threads.emplace_back(producerLoop, std::ref(buffer), 1, 10);
    threads.emplace_back(producerLoop, std::ref(buffer), 2, 10);
    threads.emplace_back(consumerLoop, std::ref(buffer), 1, 10);
    threads.emplace_back(consumerLoop, std::ref(buffer), 2, 10);
    for (auto& t : threads) t.join();
    return 0;
}

