// C++'s standard library has no built-in blocking queue, so this
// wraps std::queue with a mutex and condition_variable to get the
// same "put blocks when full, get blocks when empty" behavior
#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <string>

class BlockingQueue {
private:
    size_t capacity;
    std::queue<std::string> items;
    std::mutex mtx;
    std::condition_variable cv;

public:
    explicit BlockingQueue(size_t capacity) : capacity(capacity) {}

    void put(const std::string& item) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return items.size() < capacity; }); // blocks automatically if full
        items.push(item);
        cv.notify_all();
    }

    std::string take() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return !items.empty(); }); // blocks automatically if empty
        std::string item = items.front();
        items.pop();
        cv.notify_all();
        return item;
    }
};

void producer(BlockingQueue& q, int pid, int count) {
    for (int i = 0; i < count; i++) {
        q.put("item-" + std::to_string(pid) + "-" + std::to_string(i));
    }
}

void consumer(BlockingQueue& q, int cid, int count) {
    for (int i = 0; i < count; i++) {
        std::string item = q.take();
        std::cout << "consumer " << cid << " got " << item << std::endl;
    }
}

int main() {
    BlockingQueue queue(5);
    std::vector<std::thread> threads;
    threads.emplace_back(producer, std::ref(queue), 1, 10);
    threads.emplace_back(producer, std::ref(queue), 2, 10);
    threads.emplace_back(consumer, std::ref(queue), 1, 10);
    threads.emplace_back(consumer, std::ref(queue), 2, 10);
    for (auto& t : threads) t.join();
    return 0;
}
